import pandas as pd
import numpy as np

# Load data
df = pd.read_csv('chunks_csv/cyclehire_w005.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute Self-Containment Ratio for each borough
departures = df.groupby('StartBorough').size()
self_contained = df[df['StartBorough'] == df['EndBorough']].groupby('StartBorough').size()
containment_ratio = (self_contained / departures).fillna(0)

print("Self-Containment Ratios:")
print(containment_ratio.sort_values(ascending=False))

# Prepare adjacency data
adjacency_pairs = adjacency.groupby('borough')['neighbor'].apply(list).to_dict()

# Function to check if neighbors are all high/low
def check_neighbor_pattern(borough, ratio_threshold, containment_ratio, adjacency_pairs, high=True):
    if borough not in adjacency_pairs:
        return False  # Skip if no adjacency data

    neighbors = adjacency_pairs[borough]
    neighbor_ratios = [containment_ratio.get(n, 0) for n in neighbors]

    if high:
        return all(r >= ratio_threshold for r in neighbor_ratios)
    else:
        return all(r <= ratio_threshold for r in neighbor_ratios)

# Determine thresholds (median split)
median_ratio = containment_median = containment_ratio.median()
high_threshold = median_ratio
low_threshold = median_ratio

print(f"\nMedian Self-Containment Ratio: {median_ratio}")

# Identify hotspots (high ratio + high neighbors)
hotspots = []
for borough in containment_ratio.index:
    if containment_ratio[borough] >= high_threshold:
        if check_neighbor_pattern(borough, high_threshold, containment_ratio, adjacency_pairs, high=True):
            hotspots.append(borough)

# Identify coldspots (low ratio + low neighbors)
coldspots = []
for borough in containment_ratio.index:
    if containment_ratio[borough] <= low_threshold:
        if check_neighbor_pattern(borough, low_threshold, containment_ratio, adjacency_pairs, high=False):
            coldspots.append(borough)

# Prepare final answer
final_answer_parts = []
for borough in hotspots:
    final_answer_parts.append(f"{borough} (HH, ratio={containment_ratio[borough]:.3f})")
for borough in coldspots:
    final_answer_parts.append(f"{borough} (LL, ratio={containment_ratio[borough]:.3f})")

if not final_answer_parts:
    print("FINAL ANSWER: none")
else:
    print("FINAL ANSWER: " + ", ".join(final_answer_parts))
